package com.procurement.quotationcomparison.service;
import com.procurement.common.exception.*;import com.procurement.common.response.*;import com.procurement.quotationcomparison.dto.request.*;import com.procurement.quotationcomparison.dto.response.*;import com.procurement.quotationcomparison.entity.*;import com.procurement.quotationcomparison.exception.*;import com.procurement.quotationcomparison.mapper.*;import com.procurement.quotationcomparison.repository.*;import com.procurement.quotationcomparison.specification.*;import com.procurement.rfq.entity.*;import com.procurement.rfq.repository.RfqRepository;import com.procurement.vendorquotation.entity.*;import com.procurement.vendorquotation.repository.VendorQuotationRepository;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class QuotationComparisonServiceImpl implements QuotationComparisonService{private final QuotationComparisonRepository repo;private final QuotationComparisonLineRepository lines;private final ComparisonCriteriaRepository criteria;private final ComparisonScoreRepository scores;private final RfqRepository rfqs;private final VendorQuotationRepository quotations;private final QuotationComparisonMapper mapper;public QuotationComparisonServiceImpl(QuotationComparisonRepository r,QuotationComparisonLineRepository l,ComparisonCriteriaRepository c,ComparisonScoreRepository s,RfqRepository f,VendorQuotationRepository q,QuotationComparisonMapper m){repo=r;lines=l;criteria=c;scores=s;rfqs=f;quotations=q;mapper=m;}private String user(){var a=SecurityContextHolder.getContext().getAuthentication();return a==null?"system":a.getName();}private QuotationComparison find(Long id){return repo.findById(id).orElseThrow(()->new QuotationComparisonNotFoundException(id));}private void draft(QuotationComparison c){if(c.getStatus()==ComparisonStatus.APPROVED||c.getStatus()==ComparisonStatus.CANCELLED)throw new ConflictException("Comparison cannot be changed");}
@Transactional public QuotationComparisonResponse create(QuotationComparisonRequest r){var f=rfqs.findById(r.rfqId()).orElseThrow(()->new ResourceNotFoundException("RFQ not found: "+r.rfqId()));if(repo.existsByRfqId(r.rfqId()))throw new ConflictException("RFQ already has a comparison");var c=QuotationComparison.builder().comparisonNumber("QC-"+Year.now().getValue()+"-"+String.format("%06d",repo.count()+1)).rfq(f).comparisonMethod(r.comparisonMethod()).comparisonDate(LocalDate.now()).preparedBy(user()).createdBy(user()).updatedBy(user()).remarks(r.remarks()).build();return mapper.comparison(repo.save(c));}
@Transactional(readOnly=true)public PageResponse<QuotationComparisonResponse>search(String k,ComparisonMethod m,ComparisonStatus s,Pageable p){Page<QuotationComparisonResponse>x=repo.findAll(QuotationComparisonSpecification.search(k,m,s),p).map(mapper::comparison);return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public QuotationComparisonResponse get(Long id){return mapper.comparison(find(id));}@Transactional public QuotationComparisonResponse update(Long id,QuotationComparisonRequest r){var c=find(id);draft(c);c.setComparisonMethod(r.comparisonMethod());c.setRemarks(r.remarks());return mapper.comparison(repo.save(c));}@Transactional public void delete(Long id){var c=find(id);draft(c);repo.delete(c);}
@Transactional public QuotationComparisonResponse generate(Long id){var c=find(id);if(c.getRfq().getStatus()!=RfqStatus.CLOSED)throw new ConflictException("RFQ must be CLOSED");if(!lines.findByComparisonIdOrderByRankAsc(id).isEmpty())throw new ConflictException("Comparison already generated");var qs=quotations.findAll((r,q,b)->b.and(b.equal(r.get("rfq").get("id"),c.getRfq().getId()),b.equal(r.get("status"),VendorQuotationStatus.SUBMITTED)));if(qs.size()<2)throw new ConflictException("At least two submitted quotations are required");var min=qs.stream().map(VendorQuotation::getGrandTotal).min(BigDecimal::compareTo).orElse(BigDecimal.ONE);var i=0;for(var q:qs){BigDecimal price=min.multiply(BigDecimal.valueOf(100)).divide(q.getGrandTotal(),2,RoundingMode.HALF_UP);BigDecimal delivery=q.getDeliveryDays()==null?BigDecimal.ZERO:BigDecimal.valueOf(Math.max(0,100-q.getDeliveryDays()));BigDecimal overall=price.multiply(BigDecimal.valueOf(40)).add(delivery.multiply(BigDecimal.valueOf(10))).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);lines.save(QuotationComparisonLine.builder().comparison(c).vendorQuotation(q).vendor(q.getVendor()).priceScore(price).technicalScore(BigDecimal.ZERO).qualityScore(BigDecimal.ZERO).deliveryScore(delivery).warrantyScore(q.getWarrantyMonths()==null?BigDecimal.ZERO:BigDecimal.valueOf(Math.min(100,q.getWarrantyMonths()))).commercialScore(price).overallScore(overall).rank(++i).recommended(false).build());}c.setStatus(ComparisonStatus.GENERATED);return mapper.comparison(repo.save(c));}
@Transactional public QuotationComparisonResponse recommend(Long id,Long quotationId){var c=find(id);if(c.getStatus()!=ComparisonStatus.GENERATED&&c.getStatus()!=ComparisonStatus.UNDER_REVIEW)throw new ConflictException("Comparison is not ready for recommendation");var found=lines.findByComparisonIdOrderByRankAsc(id);var target=found.stream().filter(x->x.getVendorQuotation().getId().equals(quotationId)).findFirst().orElseThrow(()->new ResourceNotFoundException("Quotation is not part of comparison"));found.forEach(x->x.setRecommended(x==target));lines.saveAll(found);c.setStatus(ComparisonStatus.UNDER_REVIEW);return mapper.comparison(repo.save(c));}
@Transactional public QuotationComparisonResponse approve(Long id){var c=find(id);var winner=lines.findByComparisonIdOrderByRankAsc(id).stream().filter(QuotationComparisonLine::getRecommended).findFirst().orElseThrow(()->new ConflictException("Recommend a quotation first"));for(var l:lines.findByComparisonIdOrderByRankAsc(id)){l.getVendorQuotation().setStatus(l==winner?VendorQuotationStatus.ACCEPTED:VendorQuotationStatus.REJECTED);quotations.save(l.getVendorQuotation());}c.getRfq().setStatus(RfqStatus.AWARDED);c.setStatus(ComparisonStatus.APPROVED);c.setApprovedBy(user());return mapper.comparison(repo.save(c));}@Transactional public QuotationComparisonResponse reject(Long id){var c=find(id);c.setStatus(ComparisonStatus.REJECTED);return mapper.comparison(repo.save(c));}@Transactional(readOnly=true)public PageResponse<QuotationComparisonLineResponse>lines(Long id,Pageable p){Page<QuotationComparisonLineResponse>x=lines.findByComparisonIdOrderByRankAsc(id).stream().map(mapper::line).collect(java.util.stream.Collectors.collectingAndThen(java.util.stream.Collectors.toList(),l->new PageImpl<>(l,p, l.size())));return new PageResponse<>(x.getContent(),x.getNumber(),x.getSize(),x.getTotalElements(),x.getTotalPages(),x.isLast());}@Transactional(readOnly=true)public QuotationComparisonLineResponse line(Long id){return lines.findById(id).map(mapper::line).orElseThrow(()->new ResourceNotFoundException("Comparison line not found: "+id));}}
